/**
 * When this bundle was built, replaced at compile time by `vite.config.ts`.
 *
 * A till caches the whole app on purpose (`D-078`), so "is this terminal on the
 * new version?" is a question with no answer visible from the screen. This is
 * that answer, printed under the logo on the sign-in view (`D-100`).
 */
declare const __RPOS_BUILD__: string;
